-- ============================================================
-- STEP 1: Create monthly_sales_summary table
-- ============================================================
CREATE TABLE IF NOT EXISTS public.monthly_sales_summary (
    year_month              VARCHAR(7)      NOT NULL,
    total_invoices          INTEGER         NOT NULL DEFAULT 0,
    total_revenue           DECIMAL(10, 2)  NOT NULL DEFAULT 0.00,
    total_tracks_sold       INTEGER         NOT NULL DEFAULT 0,
    average_invoice_value   DECIMAL(10, 2)  NOT NULL DEFAULT 0.00,
    unique_customers        INTEGER         NOT NULL DEFAULT 0,
    PRIMARY KEY (year_month)
);

COMMENT ON TABLE  public.monthly_sales_summary                      IS 'Monthly aggregated sales metrics derived from Invoice and InvoiceLine data.';
COMMENT ON COLUMN public.monthly_sales_summary.year_month           IS 'Month identifier in YYYY-MM format (e.g. 2009-01).';
COMMENT ON COLUMN public.monthly_sales_summary.total_invoices        IS 'Number of invoices issued in that month.';
COMMENT ON COLUMN public.monthly_sales_summary.total_revenue         IS 'Sum of all invoice totals for the month.';
COMMENT ON COLUMN public.monthly_sales_summary.total_tracks_sold     IS 'Total quantity of individual track lines sold in the month.';
COMMENT ON COLUMN public.monthly_sales_summary.average_invoice_value IS 'Average value per invoice for the month.';
COMMENT ON COLUMN public.monthly_sales_summary.unique_customers      IS 'Count of distinct customers who made at least one purchase in the month.';
"}

{"query": "
-- ============================================================
-- STEP 2: Create top_music_charts table
-- ============================================================
CREATE TABLE IF NOT EXISTS public.top_music_charts (
    chart_type      VARCHAR(20)     NOT NULL,
    rank_position   INTEGER         NOT NULL,
    item_id         INTEGER         NOT NULL,
    item_name       VARCHAR(255)    NOT NULL,
    total_revenue   DECIMAL(10, 2)  NOT NULL DEFAULT 0.00,
    PRIMARY KEY (chart_type, rank_position),
    CONSTRAINT chk_chart_type     CHECK (chart_type IN ('top_tracks', 'top_albums', 'top_artists')),
    CONSTRAINT chk_rank_position  CHECK (rank_position BETWEEN 1 AND 10)
);

COMMENT ON TABLE  public.top_music_charts              IS 'Top-10 rankings for tracks, albums, and artists based on sales revenue / quantity.';
COMMENT ON COLUMN public.top_music_charts.chart_type   IS 'Category of chart: top_tracks, top_albums, or top_artists.';
COMMENT ON COLUMN public.top_music_charts.rank_position IS 'Rank from 1 (highest) to 10 (lowest) within the chart type.';
COMMENT ON COLUMN public.top_music_charts.item_id      IS 'Primary key of the ranked entity (TrackId, AlbumId, or ArtistId).';
COMMENT ON COLUMN public.top_music_charts.item_name    IS 'Display name of the track, album, or artist.';
COMMENT ON COLUMN public.top_music_charts.total_revenue IS 'Total revenue (or quantity-based metric) driving the ranking.';
"}
